// DB connection FORA do handler — reusa entre invocations (warm)
import { Pool } from 'pg';
const pool = new Pool({ connectionString: process.env.DB_URL });

export const handler = async (event) => {
  const client = await pool.connect();
  try {
    return await client.query(...);
  } finally {
    client.release();
  }
};
// Cold start paga o setup uma vez. Warm invocations reusam.
